-- PT116-S2-Q1. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT116-S2-Q1$batch07$ AND q.stimulus=$batch07$Pettengill: Bebop jazz musicians showed their distaste for jazz classics by taking great liberties with them, as though the songs could be made interesting only through radical reshaping.
Romney: Only compelling, versatile songs can stand such radical reshaping. Bebop musicians recognized this, and their revolutionary approach to the jazz classics enabled them to discover previously unknown depths in the music.$batch07$ AND q.prompt=$batch07$Pettengill and Romney disagree over whether$batch07$ AND q.correct_choice=$batch07$C$batch07$) THEN RAISE EXCEPTION 'Question changed: PT116-S2-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT116-S2-Q1$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S2-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT116-S2-Q1$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Pettengill's Position$batch07$, $batch07$By taking great liberties with the jazz classics, bebop musicians showed distaste for them.$batch07$), (1, $batch07$Romney's Position$batch07$, $batch07$Only strong songs can survive that kind of reshaping. Bebop musicians knew this, so the reshaping shows they valued the classics and found new depth in them.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Both agree on the fact: bebop radically reshaped the classics. They disagree about what the reshaping *meant*. Pettengill reads it as contempt. Romney reads it as respect.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether reshaping the classics showed appreciation or distaste.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT116-S2-Q1$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Pettengill describes "radical reshaping" and Romney repeats the phrase. Neither denies bebop was radically different.$batch07$), ($batch07$B$batch07$, $batch07$This is the most popular wrong answer. Romney says bebop found new depths in the classics, which is not the same as saying bebop was *better* than them. Pettengill never ranks the two either.$batch07$), ($batch07$C$batch07$, $batch07$Pettengill: the reshaping showed "distaste". Romney: it came from recognizing the songs were compelling enough to stand it. Appreciation versus distaste.$batch07$), ($batch07$D$batch07$, $batch07$Nobody talks about what jazz needs in order to be "widely popular".$batch07$), ($batch07$E$batch07$, $batch07$Neither speaker says bebop was influenced by more conservative styles.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT116-S2-Q1$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
